<span class="line"><span style="color:#E06C75;">    FirstName</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> this</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">FirstName</span><span style="color:#ABB2BF;">;</span></span>
